-- Dormie schema, v1.
--
-- IDs are text and generated by the client (e.g. 'p-k3j9x2a'), so the app can
-- create rows while offline on the course and sync them later.
--
-- Permissions hang off groups: a group is a crew that plays together. Its
-- members (signed-in users) see and edit its players, courses and rounds.
-- A player is a name in a group; when a real user claims it, players.user_id
-- links them, and that user sees every round the player was in.

create table users (
  id          text primary key,             -- Neon Auth user id
  email       text,
  name        text,
  created_at  timestamptz not null default now()
);

create table groups (
  id          text primary key,
  name        text not null,
  created_by  text not null references users(id),
  created_at  timestamptz not null default now()
);

create table group_members (
  group_id    text not null references groups(id) on delete cascade,
  user_id     text not null references users(id) on delete cascade,
  role        text not null default 'member' check (role in ('owner', 'member')),
  joined_at   timestamptz not null default now(),
  primary key (group_id, user_id)
);
create index group_members_user_idx on group_members(user_id);

create table group_invites (
  code        text primary key,
  group_id    text not null references groups(id) on delete cascade,
  player_id   text,                          -- optional: joining claims this player
  created_by  text not null references users(id),
  created_at  timestamptz not null default now(),
  expires_at  timestamptz
);

create table players (
  id                text primary key,
  group_id          text not null references groups(id) on delete cascade,
  user_id           text references users(id) on delete set null,
  name              text not null,
  handicap_index    numeric(3,1),
  color             text,
  archived_at       timestamptz,               -- hidden from pickers, kept for history
  created_at        timestamptz not null default now(),
  updated_at        timestamptz not null default now()
);
create index players_group_idx on players(group_id);
create index players_user_idx on players(user_id);
create unique index players_group_user_uniq on players(group_id, user_id) where user_id is not null;

create table courses (
  id            text primary key,
  group_id      text not null references groups(id) on delete cascade,
  name          text not null,
  par           smallint[] not null check (cardinality(par) = 18),
  stroke_index  smallint[] not null check (cardinality(stroke_index) = 18),
  last_tee_id   text,
  archived_at   timestamptz,
  created_at    timestamptz not null default now(),
  updated_at    timestamptz not null default now()
);
create index courses_group_idx on courses(group_id);

create table tee_sets (
  id         text primary key,
  course_id  text not null references courses(id) on delete cascade,
  name       text not null,
  rating     numeric(4,1) not null,
  slope      smallint not null,
  sort       smallint not null default 0
);
create index tee_sets_course_idx on tee_sets(course_id);

create table rounds (
  id               text primary key,
  group_id         text not null references groups(id) on delete cascade,
  course_id        text references courses(id) on delete set null,
  tee_set_id       text,
  -- The course as played (name, tee, rating, slope, par, stroke index), frozen
  -- so editing a course later never changes an old round's money.
  course_snapshot  jsonb not null,
  -- The Nassau setup: format, stakes, handicap rules, presses, matches.
  game             jsonb not null,
  status           text not null default 'live' check (status in ('live', 'final')),
  current_hole     smallint not null default 0,
  created_by       text not null references users(id),
  started_at       timestamptz not null default now(),
  finished_at      timestamptz,
  updated_at       timestamptz not null default now(),
  deleted_at       timestamptz
);
create index rounds_group_started_idx on rounds(group_id, started_at desc);

create table round_players (
  round_id        text not null references rounds(id) on delete cascade,
  player_id       text not null references players(id),
  seat            smallint not null,
  name            text not null,                -- as of the round
  handicap_index  numeric(3,1),                 -- as of the round
  color           text,
  primary key (round_id, player_id)
);
create index round_players_player_idx on round_players(player_id);

-- One row per player per hole, so two phones scoring the same round only
-- conflict when they edit the same cell.
create table scores (
  round_id    text not null,
  player_id   text not null,
  hole        smallint not null check (hole between 0 and 17),
  gross       smallint check (gross between 1 and 20),
  updated_by  text references users(id),
  updated_at  timestamptz not null default now(),
  primary key (round_id, player_id, hole),
  foreign key (round_id, player_id) references round_players(round_id, player_id) on delete cascade
);

create table presses (
  id          text primary key,
  round_id    text not null references rounds(id) on delete cascade,
  match_id    text not null,
  segment     text not null check (segment in ('front', 'back', 'overall')),
  start_hole  smallint not null check (start_hole between 0 and 17),
  by_side     text not null check (by_side in ('a', 'b')),
  created_by  text references users(id),
  created_at  timestamptz not null default now()
);
create index presses_round_idx on presses(round_id);

-- Who won what from whom, written when a round is finished (and removed if
-- it is reopened). Each row is one winner-loser pair for the whole round,
-- so "me vs Danny, all time" is a simple sum.
create table ledger_entries (
  round_id   text not null references rounds(id) on delete cascade,
  winner_id  text not null references players(id),
  loser_id   text not null references players(id),
  amount     numeric(10,2) not null check (amount > 0),
  created_at timestamptz not null default now(),
  primary key (round_id, winner_id, loser_id),
  check (winner_id <> loser_id)
);
create index ledger_winner_idx on ledger_entries(winner_id);
create index ledger_loser_idx on ledger_entries(loser_id);

-- Money that actually changed hands, to net against the ledger.
create table payments (
  id           text primary key,
  group_id     text not null references groups(id) on delete cascade,
  from_id      text not null references players(id),
  to_id        text not null references players(id),
  amount       numeric(10,2) not null check (amount > 0),
  round_id     text references rounds(id) on delete set null,  -- optional: settling a specific round
  note         text,
  paid_at      timestamptz not null default now(),
  recorded_by  text not null references users(id),
  created_at   timestamptz not null default now(),
  check (from_id <> to_id)
);
create index payments_from_idx on payments(from_id);
create index payments_to_idx on payments(to_id);
